class ASTNode:
    def __init__(self, value=None, left=None, right=None, op=None):
        self.value = value
        self.left = left
        self.right = right
        self.op = op

def tokenize(expr):
    lexer = shlex.shlex(expr)
    lexer.wordchars += '+-*/()'
    return list(lexer)

def build_ast(tokens):
    def parse_expr(tokens):
        node = parse_term(tokens)
        while tokens and tokens[0] in '+-':
            op = tokens.pop(0)
            right = parse_term(tokens)
            node = ASTNode(op=op, left=node, right=right)
        return node

    def parse_term(tokens):
        node = parse_factor(tokens)
        while tokens and tokens[0] in '*/':
            op = tokens.pop(0)
            right = parse_factor(tokens)
            node = ASTNode(op=op, left=node, right=right)
        return node

    def parse_factor(tokens):
        token = tokens.pop(0)
        if token.isdigit():
            return ASTNode(value=int(token))
        elif token == '(':
            node = parse_expr(tokens)
            tokens.pop(0)  # discard ')'
            return node

    tokens = list(reversed(tokens))
    return parse_expr(tokens)

def evaluate(node):
    if node.op is None:
        return node.value

    left = evaluate(node.left)
    right = evaluate(node.right)

    if node.op == '+':
        return left + right
    elif node.op == '-':
        return left - right
    elif node.op == '*':
        return left * right
    elif node.op == '/':
        return left // right

def solve(expr):
    tokens = tokenize(expr)
    node = build_ast(tokens)
    return evaluate(node)
