import operator

def solve(expr):
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2,
    }

    def get_precedence(op):
        return precedence.get(op, 0)

    def apply_operator(op, a, b):
        return {
            '+': operator.add,
            '-': operator.sub,
            '*': operator.mul,
            '/': operator.floordiv,
        }[op](a, b)

    def evaluate(expr):
        tokens = re.findall(r'\d+|\S', expr)
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            elif token in precedence:
                while stack and get_precedence(stack[-1]) >= get_precedence(token):
                    b = stack.pop()
                    a = stack.pop()
                    op = stack.pop()
                    stack.append(apply_operator(op, a, b))
                stack.append(token)
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack and stack[-1] != '(':
                    b = stack.pop()
                    a = stack.pop()
                    op = stack.pop()
                    stack.append(apply_operator(op, a, b))
                stack.pop()  # Remove '('
        while len(stack) > 1:
            b = stack.pop()
            a = stack.pop()
            op = stack.pop()
            stack.append(apply_operator(op, a, b))
        return stack[0]

    return evaluate(expr)
