    graph = {task: set(deps) for task, deps in deps.items()}
    in_degree = {task: 0 for task in deps}
    for task, deps in deps.items():
        for dep in deps:
            in_degree[task] += 1
            graph[dep].add(task)

    zero_in_degree = [task for task, degree in in_degree.items() if degree == 0]
    sorted_tasks = []

    while zero_in_degree:
        zero_in_degree.sort()
        task = zero_in_degree.pop(0)
        sorted_tasks.append(task)
        for dep in graph[task]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                zero_in_degree.append(dep)

    if len(sorted_tasks) != len(deps):
        raise ValueError("Graph contains a cycle")

