    lines = []
    words = text.split()
    line = ''
    for word in words:
        if len(line) + len(word) + 1 > width:
            lines.append(line.strip())
            line = ''
        if len(word) > width:
            lines.append(word)
        else:
            line += word + ' '
    if line:
        lines.append(line.strip())
    return lines if lines else []
```

