def flatten(d):
    result = {}
    def _flatten(d, prefix=''):
        if isinstance(d, dict):
            for k, v in d.items():
                _flatten(v, prefix + k + '.')
        elif isinstance(d, list):
            for i, v in enumerate(d):
                _flatten(v, prefix + str(i) + '.')
        else:
            result[prefix[:-1]] = d
    _flatten(d)
    return result
