def shortest(graph, start, goal):
    queue = [(0, [start])]
    visited = set()

    while queue:
        (cost, path) = queue.pop(0)
        node = path[-1]

        if node == goal:
            return (cost, path)

        if node not in visited:
            visited.add(node)
            for (neighbor, weight) in graph[node]:
                new_cost = cost + weight
                new_path = path + [neighbor]
                queue.append((new_cost, new_path))

    return (None, [])
